export async function seedContent(
  db: PrismaClient,
  systemIdentityId?: string
): Promise<void> {
  // Translation.updatedByIdentityId is a FK to identity. Ensure a stable
  // system identity exists to author seeded translations (the literal 'system'
  // string is not a real row and violated the FK).
  let identityId = systemIdentityId;
  if (!identityId) {
    const system = await db.identity.upsert({
      where: { email: 'system@myuno.internal' },
      update: {},
      create: {
        firstName: 'myUNO',
        lastName: 'System',
        email: 'system@myuno.internal',
        status: 'active',
        preferredLocale: 'en',
        isAdmin: true,
      },
      select: { id: true },
    });
    identityId = system.id;
  }

  for (const keyDef of [...COMMON_KEYS, ...TRUST_LEGAL_PAGE_KEYS, ...UI_SHELL_KEYS, ...HOME_KEYS, ...ADMIN_S3_KEYS, ...SERVICE_DETAIL_KEYS, ...SERVICE_ORDER_DETAIL_KEYS, ...PROJECT_PAGE_KEYS, ...LEAD_FORM_KEYS, ...AUDIENCE_EXPANSION_KEYS, ...CATALOG_LABEL_KEYS, ...AREA_LABEL_KEYS, ...ONBOARDING_KEYS, ...ACCOUNT_KEYS, ...STATUS_LABEL_KEYS]) {
    // Ensure content key exists
    await ensureContentKey(
      db,
      keyDef.key,
      keyDef.namespace,
      keyDef.description,
      keyDef.supportsRich || false
    );

    // Set translations for all provided locales
    const locales: Locale[] = ['ru', 'en', 'th', 'zh'];
    for (const locale of locales) {
      const value = keyDef[locale];
      if (value === undefined) continue;
      await setTranslation(
        db,
        keyDef.key,
        locale,
        value,
        keyDef.status || 'ok',
        identityId
      );
    }
  }
}
